scripts.command:
jjs
var FileWriter = Java.type('java.io.FileWriter');
var fw=new FileWriter('#{lotl_gtfobins_output_file}');
fw.write('#{lotl_gtfobins_data}');
fw.close();

echo '...' >#{lotl_gtfobins_local_path}
nmap --script=#{lotl_gtfobins_local_path}
lua -e 'local f=io.open("#{lotl_gtfobins_output_file}", "wb"); f:write("#{lotl_gtfobins_data}"); io.close(f);'

echo '...' >#{lotl_gtfobins_local_path}
pandoc -L #{lotl_gtfobins_local_path} /dev/null
lua -e 'local f=io.open("#{lotl_gtfobins_output_file}", "wb"); f:write("#{lotl_gtfobins_data}"); io.close(f);'

echo #{lotl_gtfobins_data} >#{lotl_gtfobins_local_path}
tar cf #{lotl_gtfobins_local_path}.tar #{lotl_gtfobins_local_path}
tar Pxf #{lotl_gtfobins_local_path}.tar --xform s@.*@#{lotl_gtfobins_output_file}@

echo '...' >#{lotl_gtfobins_local_path}
tshark -Xlua_script:#{lotl_gtfobins_local_path}
lua -e 'local f=io.open("#{lotl_gtfobins_output_file}", "wb"); f:write("#{lotl_gtfobins_data}"); io.close(f);'
